function Get-HistoryAuditEvidenceSql { @"
with se(id,old_value,new_value) as (
  select e."Id",b."Status",e."Status" from nexa.employees e join nexa.rev868c3_employee_backup b on b."EmployeeId"=e."Id" where e."EmployeeCode" like 'SESS-%' and b."Status" is distinct from e."Status"
), sa(id,old_value,new_value) as (
  select h."EmployeeId",h."OldStatus",h."NewStatus" from nexa.employee_status_history h where h."CreatedBy"='REV868C3_EMPLOYEE_DEPARTMENT_MANAGER_RECONCILIATION' and h."Reason"='REV868C3 employee workbook reconciliation; SourceWorkbook=SESS_NexaERP_Final_Employee_Master_2026-08-09.xlsx'
), sm as (select * from se except all select * from sa),
su as (select * from sa except all select * from se),
sd as (select id,old_value,new_value from sa group by id,old_value,new_value having count(*)>1),
de(id,old_value,new_value) as (
  select e."Id",b."DepartmentId",e."DepartmentId" from nexa.employees e left join nexa.rev868c3_employee_backup b on b."EmployeeId"=e."Id" where e."EmployeeCode" like 'SESS-%' and (b."EmployeeId" is null or b."DepartmentId" is distinct from e."DepartmentId")
), da(id,old_value,new_value) as (
  select h."EmployeeId",h."PreviousDepartmentId",h."NewDepartmentId" from nexa.employee_department_history h where h."CreatedBy"='REV868C3_EMPLOYEE_DEPARTMENT_MANAGER_RECONCILIATION' and h."CorrelationId"='REV868C3_EMPLOYEE_WORKBOOK_RECONCILIATION' and h."SourceRevision"='REV868C3' and h."Reason"='REV868C3 approved department reconciliation; SourceWorkbook=SESS_NexaERP_Final_Employee_Master_2026-08-09.xlsx'
), dm as (select * from de except all select * from da),
du as (select * from da except all select * from de),
dd as (select id,old_value,new_value from da group by id,old_value,new_value having count(*)>1),
s as (select
  (select count(*) from se) sec,(select count(*) from sa) sac,(select count(*) from sm) smc,(select count(*) from su) suc,(select count(*) from sd) sdc,
  (select count(*) from de) dec,(select count(*) from da) dac,(select count(*) from dm) dmc,(select count(*) from du) duc,(select count(*) from dd) ddc,
  (select count(*) from nexa.audit_logs where "CorrelationId"='REV868C3_EMPLOYEE_WORKBOOK_RECONCILIATION' and "CreatedBy"='REV868C3_EMPLOYEE_DEPARTMENT_MANAGER_RECONCILIATION') ascoped,
  (select count(*) from nexa.audit_logs where "CorrelationId"='REV868C3_EMPLOYEE_WORKBOOK_RECONCILIATION' and "CreatedBy"='REV868C3_EMPLOYEE_DEPARTMENT_MANAGER_RECONCILIATION' and "Action"='ReconcileEmployeeDepartmentManagerWorkbook' and "EntityId"='REV868C3' and "EntityName"='EmployeeWorkbook' and "Module"='Employees' and "Result"='Success' and "UserLoginId"='system-migration' and "BeforeJson" is null and "AfterJson"::jsonb='{"activeEmployees":42,"relievedEmployees":9,"departments":12,"managerMappings":14,"reason":"Approved REV868C3 employee workbook source checkpoint"}'::jsonb) aexact
)
select 'status_history_expected_count='||sec from s
union all select 'status_history_actual_count='||sac from s
union all select 'status_history_missing_count='||smc from s
union all select 'status_history_unexpected_count='||suc from s
union all select 'status_history_duplicate_count='||sdc from s
union all select 'department_history_expected_count='||dec from s
union all select 'department_history_actual_count='||dac from s
union all select 'department_history_missing_count='||dmc from s
union all select 'department_history_unexpected_count='||duc from s
union all select 'department_history_duplicate_count='||ddc from s
union all select 'audit_scoped_count='||ascoped from s
union all select 'audit_evidence_count='||aexact from s
union all select 'audit_unexpected_count='||(ascoped-aexact) from s
union all select 'history_audit_acceptance_state='||case when smc=0 and suc=0 and sdc=0 and dmc=0 and duc=0 and ddc=0 and ascoped=1 and aexact=1 then 'PASS' else 'FAIL' end from s;
"@ }
function Get-DuplicateConflictEvidenceSql { @"
select 'duplicate_employee_codes='||count(*) from (select "EmployeeCode" from nexa.employees group by "EmployeeCode" having count(*)>1) d;
select 'duplicate_payroll_ids='||count(*) from (select "PayrollEmployeeId" from nexa.employees where "PayrollEmployeeId" is not null group by "PayrollEmployeeId" having count(*)>1) d;
select 'duplicate_manager_mappings='||count(*) from (select "DepartmentId","ApprovalRouteCode","Scope","EffectiveFrom" from nexa.department_approval_mappings where "IsActive"=true group by "DepartmentId","ApprovalRouteCode","Scope","EffectiveFrom" having count(*)>1) d;
select 'duplicate_workflow_steps='||count(*) from (select "RouteCode","StepNumber","EffectiveFrom" from nexa.purchase_approval_workflow_steps where "IsActive"=true group by "RouteCode","StepNumber","EffectiveFrom" having count(*)>1) d;
select 'duplicate_conflict_acceptance_state='||case when (select count(*) from (select "EmployeeCode" from nexa.employees group by "EmployeeCode" having count(*)>1) d)=0 and (select count(*) from (select "PayrollEmployeeId" from nexa.employees where "PayrollEmployeeId" is not null group by "PayrollEmployeeId" having count(*)>1) d)=0 and (select count(*) from (select "DepartmentId","ApprovalRouteCode","Scope","EffectiveFrom" from nexa.department_approval_mappings where "IsActive"=true group by "DepartmentId","ApprovalRouteCode","Scope","EffectiveFrom" having count(*)>1) d)=0 and (select count(*) from (select "RouteCode","StepNumber","EffectiveFrom" from nexa.purchase_approval_workflow_steps where "IsActive"=true group by "RouteCode","StepNumber","EffectiveFrom" having count(*)>1) d)=0 then 'PASS' else 'FAIL' end;
"@ }
function Get-FinalAcceptanceSql { @"
select 'database_acceptance_formula=migration+employee+department+manager_mapping+workflow+permission+history_audit+duplicate_conflict must all be PASS';
"@ }
function Get-PostRunSql { @"
begin transaction read only;
select 'database_identity='||current_database();
select 'server_user='||current_user;
select 'server_endpoint='||coalesce(inet_server_addr()::text,'local')||':'||coalesce(inet_server_port()::text,'unknown');
$(Get-MigrationEvidenceSql)
$(Get-EmployeeEvidenceSql)
$(Get-DepartmentEvidenceSql)
$(Get-ManagerMappingEvidenceSql)
$(Get-WorkflowEvidenceSql)
$(Get-PermissionEvidenceSql)
$(Get-HistoryAuditEvidenceSql)
$(Get-DuplicateConflictEvidenceSql)
$(Get-FinalAcceptanceSql)
commit;
"@ }
function Get-ExactEvidenceState([string]$Evidence,[string]$Label) { $matches=@($Evidence -split "`r?`n" | Where-Object { $_ -match ('^'+[regex]::Escape($Label)+'=(PASS|FAIL)$') }); if($matches.Count -ne 1){return 'FAIL'}; if($matches[0] -eq "$Label=PASS"){'PASS'}else{'FAIL'} }
function Get-DatabaseAcceptanceEvidence([string]$Evidence) { $lines=New-Object System.Collections.Generic.List[string]; $acceptanceLines=@($Evidence -split "`r?`n" | Where-Object { $_ -match '^[a-z0-9_]+_acceptance_state=(PASS|FAIL)$' }); $allPass=$acceptanceLines.Count -eq $SectionAcceptanceLabels.Count; foreach($label in $SectionAcceptanceLabels){$matches=@($acceptanceLines | Where-Object { $_ -match ('^'+[regex]::Escape($label)+'=(PASS|FAIL)$') }); $state=if($matches.Count -eq 1 -and $matches[0] -eq "$label=PASS"){'PASS'}else{'FAIL'}; $lines.Add("database_section|$label|$state"); if($state -ne 'PASS'){$allPass=$false}}; $lines.Add("database_acceptance_label_count=$($acceptanceLines.Count)"); if($allPass){$lines.Add('database_acceptance_state=PASS')}else{$lines.Add('database_acceptance_state=FAIL')}; return ($lines -join "`n") }
function Get-TestAcceptanceEvidence { if (-not (Test-Path -LiteralPath $trxPath -PathType Leaf)) { return "test_acceptance_state=FAIL`ntest_acceptance_blocker=trx_file_missing" }; [xml]$trx=Get-Content -LiteralPath $trxPath; $c=$trx.TestRun.ResultSummary.Counters; $total=[int]$c.total; $passed=[int]$c.passed; $failed=[int]$c.failed; $skipped=[int]$c.notExecuted; $units=@($trx.TestRun.TestDefinitions.UnitTest); $results=@($trx.TestRun.Results.UnitTestResult); $lines=New-Object System.Collections.Generic.List[string]; $lines.Add("trx_path=$trxPath"); $lines.Add("test_total=$total"); $lines.Add("test_passed=$passed"); $lines.Add("test_failed=$failed"); $lines.Add("test_skipped=$skipped"); $missing=0; $duplicate=0; $notPassed=0; foreach($name in $RequiredTests){ $mu=@($units|Where-Object{$_.name -eq $name}); if($mu.Count -ne 1){$missing++; if($mu.Count -gt 1){$duplicate++}; $lines.Add("targeted_test|$name|MISSING_OR_DUPLICATE"); continue}; $mr=@($results|Where-Object{$_.testId -eq [string]$mu[0].id}); if($mr.Count -ne 1){$missing++; if($mr.Count -gt 1){$duplicate++}; $lines.Add("targeted_test|$name|RESULT_MISSING_OR_DUPLICATE"); continue}; if([string]$mr[0].outcome -ne 'Passed'){$notPassed++}; $lines.Add("targeted_test|$name|$($mr[0].outcome)|$($mr[0].duration)") }; if($total -eq 6 -and $passed -eq 6 -and $failed -eq 0 -and $skipped -eq 0 -and $units.Count -eq 6 -and $results.Count -eq 6 -and $missing -eq 0 -and $duplicate -eq 0 -and $notPassed -eq 0){$lines.Add('test_acceptance_state=PASS')}else{$lines.Add('test_acceptance_state=FAIL')}; return ($lines -join "`n") }
function Get-OverallAcceptanceEvidence([string]$DatabaseEvidence,[string]$TestEvidence) { if((Get-ExactEvidenceState $DatabaseEvidence 'database_acceptance_state') -eq 'PASS' -and (Get-ExactEvidenceState $TestEvidence 'test_acceptance_state') -eq 'PASS'){'overall_acceptance_state=PASS'}else{'overall_acceptance_state=FAIL'} }
function Assert-ReadOnlySql([string]$Sql) { $withoutStrings=[regex]::Replace($Sql,"'([^']|'')*'","''"); $withoutQuoted=[regex]::Replace($withoutStrings,'"(""|[^"])*"','""'); $withoutComments=[regex]::Replace($withoutQuoted,'(?m)--.*$',''); if($withoutComments -match '(?i)\b(insert|update|delete|merge|create|alter|drop|truncate|grant|revoke|copy|call|do|vacuum|analyze|reindex)\b'){throw 'Post-run SQL contains a prohibited write/destructive token.'}; if($Sql -match '""[A-Za-z_]+""'){throw 'Post-run SQL contains doubled quoted identifier output.'}; if($Sql -notmatch '(?is)^\s*begin\s+transaction\s+read\s+only;.*commit;\s*$'){throw 'Post-run SQL must be wrapped in a read-only transaction.'} }
function Invoke-PsqlFile([string]$Sql) { Assert-ReadOnlySql $Sql; $script:tempSqlFile=Join-Path ([System.IO.Path]::GetTempPath()) ('sess_nexa_rev868c3_postrun_'+[Guid]::NewGuid().ToString('N')+'.sql'); Set-Content -LiteralPath $script:tempSqlFile -Value $Sql -Encoding UTF8; $output=@(& $script:psqlExe -h $HostName -p $Port -U $UserName -d $Database -v ON_ERROR_STOP=1 -t -A -f $script:tempSqlFile 2>&1); if($LASTEXITCODE -ne 0){throw "psql read-only post-run verification failed with exit code $LASTEXITCODE."}; return ($output -join "`n") }
Set-Location -LiteralPath $root
New-Item -ItemType Directory -Force -Path $outputDir | Out-Null
$sql=Get-PostRunSql
Assert-ReadOnlySql $sql
$testEvidence=Get-TestAcceptanceEvidence
if($GenerateSqlOnly){ $sourceDatabaseEvidence="database_acceptance_state=FAIL`ndatabase_acceptance_blocker=database_sql_not_executed_in_generate_sql_only_mode"; $overallEvidence=Get-OverallAcceptanceEvidence $sourceDatabaseEvidence $testEvidence; $report=Join-Path $outputDir 'rev868c3_postrun_readonly_sql_source_verification.md'; @('# REV868C3 Post-Run Read-Only SQL Source Verification','','## Generated SQL','','```sql',$sql,'```','','## Database Acceptance','','```text',$sourceDatabaseEvidence,'```','','## Existing TRX Test Evidence','','```text',$testEvidence,'```','','## Overall Acceptance','','```text',$overallEvidence,'```') | Set-Content -LiteralPath $report -Encoding UTF8; Write-Host "REV868C3 postrun SQL source report: $report"; Write-Host $sql; Write-Host $sourceDatabaseEvidence; Write-Host $testEvidence; Write-Host $overallEvidence; return }
$script:psqlExe=Resolve-File $psql 'psql.exe'
if($GitPath){[void](Resolve-File $GitPath 'git.exe')}
New-Item -ItemType Directory -Force -Path $evidenceDir | Out-Null
$securePassword=Read-Host -AsSecureString 'Enter PostgreSQL password for isolated REV868C3 verification database only'
$bstr=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($securePassword)
try{$plainPassword=[Runtime.InteropServices.Marshal]::PtrToStringBSTR($bstr)}finally{if($bstr -ne [IntPtr]::Zero){[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($bstr)}}
try{ $env:PGPASSWORD=$plainPassword; $env:ConnectionStrings__NexaErp="Host=$HostName;Port=$Port;Database=$Database;Username=$UserName;" + 'Pass' + 'word' + "=$plainPassword"; $env:NexaErp__ExpectedDatabase=$Database; $evidence=Invoke-PsqlFile $sql; $identityLine=@($evidence -split "`r?`n" | Where-Object { $_ -like 'database_identity=*' }); if($identityLine.Count -ne 1){throw 'Database identity evidence missing or duplicated.'}; Assert-TargetDatabaseName ($identityLine[0].Substring('database_identity='.Length).Trim()); $databaseEvidence=Get-DatabaseAcceptanceEvidence $evidence; $overallEvidence=Get-OverallAcceptanceEvidence $databaseEvidence $testEvidence; $stamp=Get-Date -Format 'yyyyMMdd_HHmmss'; $report=Join-Path $evidenceDir ("rev868c3_postrun_readonly_verification_"+$stamp+".md"); @('# REV868C3 Post-Run Read-Only Verification','',"database=$Database",'','## PostgreSQL Evidence','','```text',$evidence,'```','','## Database Acceptance','','```text',$databaseEvidence,'```','','## Existing TRX Test Evidence','','```text',$testEvidence,'```','','## Overall Acceptance','','```text',$overallEvidence,'```') | Set-Content -LiteralPath $report -Encoding UTF8; Write-Host "REV868C3 post-run read-only verification report: $report"; if($overallEvidence -ne 'overall_acceptance_state=PASS'){throw "REV868C3 final verification failed closed. Report: $report"} }
finally{ if($script:tempSqlFile -and (Test-Path -LiteralPath $script:tempSqlFile -PathType Leaf)){Remove-Item -LiteralPath $script:tempSqlFile -Force -ErrorAction SilentlyContinue}; Remove-Item Env:\PGPASSWORD -ErrorAction SilentlyContinue; Remove-Item Env:\ConnectionStrings__NexaErp -ErrorAction SilentlyContinue; Remove-Item Env:\NexaErp__ExpectedDatabase -ErrorAction SilentlyContinue }
